(()=>{const section=document.querySelector('.art-interlude');if(!section)return;let queued=false;const paint=()=>{queued=false;const r=section.getBoundingClientRect();const p=Math.max(0,Math.min(1,(innerHeight-r.top)/(innerHeight*.72)));section.style.setProperty('--art-progress',p.toFixed(3))};addEventListener('scroll',()=>{if(!queued){queued=true;requestAnimationFrame(paint)}},{passive:true});addEventListener('resize',paint);paint()})();
